package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.TlsClientAuthSubjectDnVO;

class TlsClientAuthSubjectDnValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of tls client auth subject dn of oauth client")
  void test_tls_client_auth_subject_dn_value_holder_assign_plain_value() {
    Object holder = new Object();
    TlsClientAuthSubjectDnValueHolder<Object> value =
        new TlsClientAuthSubjectDnValueHolder<>(holder);
    Assertions.assertSame(holder, value.tlsClientAuthSubjectDn("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getTlsClientAuthSubjectDnValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getTlsClientAuthSubjectDn().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.tlsClientAuthSubjectDnNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getTlsClientAuthSubjectDnValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getTlsClientAuthSubjectDn().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of tls client auth subject dn of oauth client")
  void test_tls_client_auth_subject_dn_value_holder_assign_value_object() {
    Object holder = new Object();
    TlsClientAuthSubjectDnValueHolder<Object> value =
        new TlsClientAuthSubjectDnValueHolder<>(holder);
    TlsClientAuthSubjectDnVO vo = TlsClientAuthSubjectDnVO.from("one");
    Assertions.assertFalse(value.getTlsClientAuthSubjectDnValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.tlsClientAuthSubjectDn(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getTlsClientAuthSubjectDnValue().orElseThrow());
    Assertions.assertSame(holder, value.tlsClientAuthSubjectDn(Optional.empty()));
    Assertions.assertFalse(value.getTlsClientAuthSubjectDnValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.tlsClientAuthSubjectDn(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTlsClientAuthSubjectDnValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of tls client auth subject dn of oauth client against the original")
  void test_tls_client_auth_subject_dn_value_holder_read() {
    Object holder = new Object();
    TlsClientAuthSubjectDnValueHolder<Object> value =
        new TlsClientAuthSubjectDnValueHolder<>(holder);
    TlsClientAuthSubjectDnVO vo = TlsClientAuthSubjectDnVO.from("one");
    TlsClientAuthSubjectDnVO other = TlsClientAuthSubjectDnVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getTlsClientAuthSubjectDnValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTlsClientAuthSubjectDn(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTlsClientAuthSubjectDn(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.tlsClientAuthSubjectDn(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTlsClientAuthSubjectDn(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTlsClientAuthSubjectDn(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of tls client auth subject dn of oauth client")
  void test_tls_client_auth_subject_dn_value_holder_unset() {
    Object holder = new Object();
    TlsClientAuthSubjectDnValueHolder<Object> value =
        new TlsClientAuthSubjectDnValueHolder<>(holder);
    TlsClientAuthSubjectDnVO vo = TlsClientAuthSubjectDnVO.from("one");
    value.tlsClientAuthSubjectDn(vo);
    Assertions.assertSame(holder,
        value.unsetTlsClientAuthSubjectDnIfMatches("tlsClientAuthSubjectDn_other"));
    Assertions.assertTrue(value.getTlsClientAuthSubjectDnValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetTlsClientAuthSubjectDnIfMatches("tlsClientAuthSubjectDn"));
    Assertions.assertFalse(value.getTlsClientAuthSubjectDnValue().isPresent(),
        "The field name must clear the value");
    value.tlsClientAuthSubjectDn(vo);
    Assertions.assertSame(holder, value.unsetTlsClientAuthSubjectDn());
    Assertions.assertFalse(value.getTlsClientAuthSubjectDnValue().isPresent(),
        "Unset must clear the value");
  }
}
